/**
 * Automation printer — walks the internal `AutomationAst` produced by the
 * platform deserializer and emits action-native EDK TypeScript source:
 * `automation({ name, app, revision, status,
 * actions: actions().trigger(...).recordSearch(...).outputs(...) })`,
 * exported as default. `automation` itself is not chained; the fluent
 * trigger/action/output sequence lives in the `actions` field.
 *
 * Where v1 emits `automation({ owner, name, status }).trigger(...)` with
 * refs carrying ids, v2 emits the chainable builder with flat `name`/`parent`
 * options and every cross-entity reference as a **handle-token** off the owning app's
 * catalog barrel (`<ownerHandle>.fields.<key>`, `<ownerHandle>.agents.<key>`,
 * `<ownerHandle>.automations.<key>`) — no ids ever surface.
 *
 * The structure mirrors the v1 printer (`./
 * print-automation.ts`): same `ImportTracker`, same `RefCtx` (the bound ctx
 * name threaded through nested operator bodies), same quote/escape/indent
 * helpers, same recursion over operator `children` via fluent branch builders. Only the
 * emitted *syntax* changes:
 *   - the builder API (`automation`, `recordCreated`, direct fluent action
 *     methods and nested `forEach`/`switch`/`forkJoin` branch builders);
 *   - references are catalog handle-tokens, not v1 typed-id objects;
 *   - filters use the `filter.*` DSL with `FieldRef` tokens (`filter.eq(app
 *     .fields.x, "v")`), passed as a bare value (not v1's `(app) => ...` lambda);
 *   - ctx refs use the v2 ctx shape (`ctx.trigger.…`, `ctx.actions.<key>.…`,
 *     and `ctx.item.…` for the current forEach item).
 *
 * Unresolved refs emit `"<uuid>" /* TODO: <hint> *\/` (v2 has no `val()`
 * wrapper — value slots accept literals directly), so the generated file still
 * compiles when the catalog is partial. Ref-only raw datamine IDs use the
 * explicit `unsafePlatformId(...)` escape hatch and retain bridge diagnostics.
 */
import type { AutomationAst } from "./ast.js";
import type { UnresolvedReferenceDiagnostic } from "../../../graph/types.js";
/** Keep the authored publish token across pull; live workflow versions are not author intent. */
export declare function preserveAuthoredAutomationRevision(freshSource: string, existingSource: string): string;
export interface PrintAutomationV2Options {
    readonly refName?: string;
    /**
     * The owning app's refName to print as `parent:`. Defaults to
     * `ast.ownerHandle` (the app the automation was extracted FROM) — a caller
     * retargeting the file to a different app (e.g. `edk clone app`) must pass
     * this explicitly, or the printed `parent:` silently keeps pointing at the
     * source app.
     */
    readonly appRefName?: string;
    /**
     * Name → refName for every app already on disk in this workspace (board
     * issue #40). A cross-app `app`/aspect reference whose name is a key here
     * prints `catalog.<refName>` instead of the literal stub.
     */
    readonly foreignAppRefNames?: ReadonlyMap<string, string>;
    readonly foreignElementRefNames?: ReadonlyMap<string, string>;
    /** Diagnostics emitted by the bridge for raw UUIDs retained in this pull. */
    readonly unresolvedReferences?: readonly UnresolvedReferenceDiagnostic[];
}
/**
 * Public entry point. Kept as a thin wrapper so call sites match the v1
 * printer's `printAutomationFinalized` convention.
 */
export declare function printAutomationV2(ast: AutomationAst, opts?: PrintAutomationV2Options): string;
